{v:8,l:["Refreia a ira e abandona o furor;","não te irrites: só farias o mal."],np:1},
{v:9,l:["Porque os malfeitores serão exterminados,","mas os que esperam no Senhor possuirão a terra."]},
{v:10,l:["Ainda um pouco, e o ímpio não existirá;","procurarás o seu lugar, e não o acharás."]},
{v:11,l:["Mas os mansos possuirão a terra","e se deleitarão na abundância da paz."],n:"Verso que Jesus retoma na terceira bem-aventurança, quase palavra por palavra."},
{v:12,l:["O ímpio trama contra o justo","e range contra ele os dentes."]},
{v:13,l:["O Senhor ri-se dele,","porque vê chegar o seu dia."]},
{v:14,l:["Os ímpios desembainham a espada e retesam o arco,","para derrubar o pobre e o necessitado,","para matar os que andam retamente."]},
{v:15,l:["A sua espada entrará no próprio coração,","e os seus arcos serão quebrados."]},
{v:16,l:["Vale mais o pouco do justo","do que a grande riqueza dos ímpios,"],np:1},
{v:17,l:["porque os braços dos ímpios serão quebrados,","mas o Senhor sustenta os justos."]},
{v:18,l:["O Senhor conhece os dias dos íntegros,","e a sua herança durará para sempre."]},
{v:19,l:["Não serão envergonhados no tempo mau,","e nos dias de fome ficarão saciados."]},
{v:20,l:["Mas os ímpios perecerão,","e os inimigos do Senhor, como o esplendor dos prados,","desaparecerão, desaparecerão como a fumaça."],n:"O hebraico deste versículo é dos mais difíceis do saltério, e as versões antigas divergem; o esplendor dos prados seria a flor que se abre de manhã e à tarde já secou."},
{v:21,l:["O ímpio pede emprestado e não devolve,","mas o justo se compadece e dá."]},
{v:22,l:["Os que o Senhor abençoa possuirão a terra,","e os que ele amaldiçoa serão exterminados."]},
{v:23,l:["O Senhor firma os passos do homem","e se compraz no seu caminho."],np:1},
{v:24,l:["Se cair, não ficará prostrado,","porque o Senhor o sustenta pela mão."]},
{v:25,l:["Fui jovem e envelheci,","e nunca vi o justo abandonado,","nem a sua descendência a mendigar o pão."],n:"O verso soa a testemunho de um velho, e não a lei geral; Jó, que viu o contrário, discutirá justamente isto."},
{v:26,l:["Todo o dia se compadece e empresta,","e a sua descendência é uma bênção."]},
{v:27,l:["Aparta-te do mal e faze o bem,","e habitarás para sempre,"]},
{v:28,l:["porque o Senhor ama o direito","e não abandona os seus fiéis.","Serão guardados para sempre,","mas a descendência dos ímpios será exterminada."]},
{v:29,l:["Os justos possuirão a terra","e nela habitarão para sempre."]},
{v:30,l:["A boca do justo medita a sabedoria,","e a sua língua fala o que é reto."],np:1},
{v:31,l:["A lei do seu Deus está no seu coração,","e os seus passos não vacilam."]},
{v:32,l:["O ímpio espreita o justo","e procura matá-lo."]},
{v:33,l:["O Senhor não o deixará na sua mão,","nem permitirá que seja condenado no juízo."]},
{v:34,l:["Espera no Senhor e guarda o seu caminho;","ele te exaltará para possuíres a terra,","e verás o extermínio dos ímpios."],np:1},
{v:35,l:["Vi o ímpio arrogante","erguer-se como cedro frondoso;"]},
{v:36,l:["passei, e eis que já não existia;","procurei-o, e não foi achado."]},
{v:37,l:["Observa o íntegro e olha para o reto,","porque há posteridade para o homem de paz."]},
{v:38,l:["Os transgressores serão todos destruídos,","e a posteridade dos ímpios será exterminada."]},
{v:39,l:["A salvação dos justos vem do Senhor:","ele é a sua fortaleza no tempo da angústia."]},
{v:40,l:["O Senhor os ajuda e os liberta;","livra-os dos ímpios e os salva,","porque nele se refugiaram."]}
